            await using(var db=new PortalDbContext(options)){await db.UserClaims.Where(x=>x.UserId==adminId&&x.ClaimValue==Permissions.ContactFilesRead).ExecuteDeleteAsync();await db.UserClaims.Where(x=>x.UserId==adminId&&x.ClaimValue==Permissions.ContactExportPii).ExecuteDeleteAsync();Check(await db.AuditLogs.AnyAsync(x=>x.Actor==adminId&&x.Action=="interaction.note")&&await db.AuditLogs.AnyAsync(x=>x.Actor==adminId&&x.Action=="contact.exported"),"Contact operation audit missing.");}
            using(var revoked=await client.GetAsync("/admin/hoi-dap/tep/"+fileId))Check(revoked.StatusCode is HttpStatusCode.Forbidden or HttpStatusCode.NotFound,"Revoked Contact file permission retained access.");using(var revoked=await client.GetAsync("/admin/hom-thu/excel?includePii=true"))Check(revoked.StatusCode==HttpStatusCode.Forbidden,"Revoked Contact PII export permission retained access.");
